window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["evaluation"]={"title":"LLM 应用评测：测量整条系统是否完成真实任务","subtitle":"把业务目标拆成可观察属性，定位检索、生成、工具与流程各自造成的失败。","thesis":"应用评测的对象不是裸模型，而是<b>输入分布 × 提示 × 检索 × 工具 × 策略 × 界面</b>构成的版本化系统。它要先把业务成功拆成可判定属性，再用组件诊断、端到端门槛和分阶段上线建立证据；总平均分不能抵消高风险退化。","quality":{"contractVersion":2,"examples":[{"section":5,"evidence":{"setup":"新版本总分从 80.0 升到 83.2","rule":"越权切片“不得低于旧版且至少 60%”","steps":"RiskLoss 从 0.682 升至 0.862","interpretation":"高风险退化不能被平均抵消"}}],"formulas":[{"id":"evaluation-measurement-error","section":4,"formulaIndex":1,"symbols":[{"name":"ScoreObserved","meaning":"评分器在样本上给出的观测分数","evidence":"输出观测分数 ScoreObserved"},{"name":"Qtrue","meaning":"不可直接完全观察的潜在真实质量","evidence":"潜在质量 Qtrue"},{"name":"Bjudge","meaning":"评分器产生的系统性偏差","evidence":"评分器系统偏差 Bjudge"},{"name":"Esample","meaning":"有限样本带来的随机误差","evidence":"样本随机误差 Esample"}]},{"id":"evaluation-weighted-risk","section":5,"formulaIndex":1,"symbols":[{"name":"PassWeighted","meaning":"按真实流量权重汇总的通过率","evidence":"输出加权通过率 PassWeighted"},{"name":"RiskLoss","meaning":"按失败概率和严重度加权的风险损失","evidence":"风险损失 RiskLoss"},{"name":"i","meaning":"评测切片编号","evidence":"切片权重"},{"name":"wi","meaning":"第 i 个切片的流量权重","evidence":"切片权重 wi"},{"name":"pi","meaning":"第 i 个切片的任务通过率","evidence":"通过率 pi"},{"name":"ci","meaning":"第 i 个切片一次失败的严重度","evidence":"失败严重度 ci"}]}],"termReviews":[],"sectionContracts":[{"section":1,"definition":{"answer":"应用评测先把业务成功写成可复现的评分契约。","evidence":"从“回答不错”改写成验收契约"},"problem":{"answer":"它解决不同评审对好答案理解不一致的问题。","evidence":"分数还能指导上线吗"},"inputOutput":{"answer":"输入样本属性评分器和版本，输出通过失败及原因。","evidence":"输出可复现的通过、失败及原因"},"mechanism":{"answer":"把任务拆成原子属性并先判硬约束再排软目标。","evidence":"硬约束先判，软目标只在可行方案间排序"},"interpretation":{"answer":"评分规则不共享时平均分无法支持发布决定。","evidence":"总分不能指导上线"},"boundary":{"answer":"安全权限等硬失败不能被文风和普通质量抵消。","evidence":"把两者先混成平均分，会让“更好听”补偿“更危险”"}},{"section":2,"definition":{"answer":"应用评测对象是从输入到业务结果的完整版本化系统链。","evidence":"评测对象是一条有边界的链"},"problem":{"answer":"它避免答案错误时不经诊断就归因于底层模型。","evidence":"怎样避免第一反应就是“换更强模型”"},"inputOutput":{"answer":"输入整条链路，输出组件诊断与端到端结果。","evidence":"输出组件诊断与端到端业务结果"},"mechanism":{"answer":"端到端决定发布，组件指标定位首次偏离。","evidence":"组件指标定位第一次偏离"},"interpretation":{"answer":"局部组件提升不等于最终业务任务提升。","evidence":"组件局部提高不代表完整任务提高"},"boundary":{"answer":"组件诊断不能代替最终端到端验收。","evidence":"诊断也不能替代最终验收"}},{"section":3,"definition":{"answer":"代表性评测集由真实分布、高损失、事故和边界案例组成。","evidence":"样本应来自任务分布而不是灵感题库"},"problem":{"answer":"它防止少量正常问题制造虚假的安全感。","evidence":"为什么会制造虚假的安全感"},"inputOutput":{"answer":"输入多类样本来源，输出带切片标签的数据集。","evidence":"输出带语言、群体、长度、工具和风险标签的数据集"},"mechanism":{"answer":"分开发、冻结、挑战和线上抽样四类用途管理。","evidence":"四者不能混用同一权重解释"},"interpretation":{"answer":"挑战集用于暴露长尾，其比例不代表生产发生率。","evidence":"挑战集比例不等于生产发生率"},"boundary":{"answer":"线上样本必须经过脱敏、权限和时间窗口治理。","evidence":"线上抽样估计真实分布"}},{"section":4,"definition":{"answer":"评分器是带系统偏差和随机误差的质量测量仪器。","evidence":"评分器是一组需要校准的测量仪器"},"problem":{"answer":"它回答 LLM 裁判合格是否等于真实质量合格。","evidence":"真实质量就一定合格吗"},"inputOutput":{"answer":"输入潜在质量偏差和误差，输出观测分数。","evidence":"输出观测分数 ScoreObserved"},"mechanism":{"answer":"用人工金标测裁判精确召回一致性和位置偏差。","evidence":"用人工金标测精确率、召回率、位置和文风偏差"},"interpretation":{"answer":"观测分数混合真实质量、系统偏差和抽样误差。","evidence":"分数是三者叠加的结果"},"boundary":{"answer":"高风险确定属性应优先使用程序或状态检查。","evidence":"应优先程序或状态检查"}},{"section":5,"definition":{"answer":"切片门禁同时计算加权通过率和严重度风险损失。","evidence":"运行示例：平均提升为何仍不能发布"},"problem":{"answer":"它解释总分上升时越权退化为何仍阻断上线。","evidence":"新版本总分从 80.0 升到 83.2，但越权率也上升，应该上线吗"},"inputOutput":{"answer":"输入权重通过率严重度，输出通过率和风险损失。","evidence":"输出加权通过率 PassWeighted 与风险损失 RiskLoss"},"mechanism":{"answer":"按权重汇总通过率，并按失败概率乘严重度汇总风险。","evidence":"后者求 Σwi×(1−pi)×ci"},"interpretation":{"answer":"风险从零点六八二升至零点八六二表示新版更危险。","evidence":"从 0.682 升至 0.862"},"boundary":{"answer":"争议成本只排优先级，越权必须由硬门槛保护。","evidence":"越权仍应用硬门槛"}},{"section":6,"definition":{"answer":"组件消融固定其他因素并只替换一个系统组件。","evidence":"组件消融把相关性变成修复线索"},"problem":{"answer":"它诊断端到端掉分来自模型检索提示工具还是渲染。","evidence":"怎样判断是模型、检索还是提示造成"},"inputOutput":{"answer":"输入同样本和单变量替换，输出端到端差异线索。","evidence":"输出检索、生成、工具或渲染对端到端差异的因果线索"},"mechanism":{"answer":"用 oracle、工具回放和规则开关隔离不同环节。","evidence":"oracle 证据消除召回限制"},"interpretation":{"answer":"消融缩小原因候选，不证明组件独立决定结果。","evidence":"消融只缩小原因候选"},"boundary":{"answer":"一次改变多个变量时不能进行可靠归因。","evidence":"一次改变多个因素无法归因"}},{"section":7,"definition":{"answer":"发布流程依次经过离线、影子、金丝雀和分级扩大。","evidence":"离线、影子、小流量与正式发布"},"problem":{"answer":"它避免离线集通过后直接全量暴露真实用户和副作用。","evidence":"为什么不能直接全量切换"},"inputOutput":{"answer":"输入各阶段结果和阈值，输出扩大停止或回滚。","evidence":"输出继续扩大、停止或回滚决定"},"mechanism":{"answer":"离线查门槛，影子查容量，金丝雀查真实交互。","evidence":"金丝雀才观察真实交互"},"interpretation":{"answer":"每一级需保持观察窗口并用稳定用户单位分流。","evidence":"每级保持观察窗口"},"boundary":{"answer":"越权尾延迟或错误预算超线必须停止扩大。","evidence":"必须自动停止扩大"}},{"section":8,"definition":{"answer":"评测治理把失败样本纳入版本化发现审核和冻结流程。","evidence":"评测集会老化，也会被团队过拟合"},"problem":{"answer":"它防止持续加题调参使门禁逐渐成为训练信号。","evidence":"为什么仍可能越测越不可信"},"inputOutput":{"answer":"输入样本治理字段，输出各数据池迁移记录。","evidence":"输出发现池、审核、开发集、冻结集及下一版本的迁移记录"},"mechanism":{"answer":"审核去重后进入开发集，下一发布周期再冻结门禁。","evidence":"当前冻结集不能因候选失败而删改"},"interpretation":{"answer":"反复针对固定失败调参会造成测试过拟合。","evidence":"会使门禁变成训练集"},"boundary":{"answer":"开放世界不可逆风险仍需要权限和人工控制。","evidence":"仍需权限和人工控制"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>把业务目标写成评分契约；区分组件与端到端指标；手算切片门槛和加权效用；建立生产失败回流闭环。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>从“回答不错”改写成验收契约<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">如果两个评审对“好答案”理解不同，分数还能指导上线吗？</p><p>先把退款助手的成功拆成原子属性：资格判断正确、金额正确、每个政策主张有证据、不承诺无权限动作、缺信息时询问、输出能被前端解析，并在延迟和成本预算内完成。每个属性都要写适用条件、证据和判定规则。</p><p>其中有些是硬约束：隐私泄漏或越权承诺出现一次就可能阻断发布；有些是软目标：措辞自然度可在合格候选间排序。把两者先混成平均分，会让“更好听”补偿“更危险”。</p><div class=\"dd-note\"><b>评分契约：</b>样本输入 + 运行上下文 + 期望属性 + 评分器 + 失败严重度 + 版本。缺任何一项，复现和归因都会变弱。</div><p>评分契约输入样本、运行上下文、期望属性、评分器、严重度和系统版本，输出可复现的通过、失败及原因。先把业务成功拆成资格、金额、证据、权限、追问、结构、延迟和成本等原子属性；硬约束先判，软目标只在可行方案间排序。评审无法共享判定规则时，总分不能指导上线。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>评测对象是一条有边界的链<span class=\"dd-badge eng\">系统</span></h2><p class=\"dd-lead\">答案错误时，怎样避免第一反应就是“换更强模型”？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 720 240\" role=\"img\" aria-label=\"退款助手从输入、检索、生成、工具到业务结果的评测分层\"><defs><marker id=\"ev1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"16\" y=\"72\" width=\"112\" height=\"68\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"72\" y=\"98\" text-anchor=\"middle\" class=\"svg-t\">真实输入</text><text x=\"72\" y=\"120\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">订单/意图/风险</text><path d=\"M128,106 L166,106\" stroke=\"#6b7484\" marker-end=\"url(#ev1)\"/><rect x=\"168\" y=\"72\" width=\"112\" height=\"68\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"224\" y=\"98\" text-anchor=\"middle\" class=\"svg-t\">检索</text><text x=\"224\" y=\"120\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">证据 Recall@5</text><path d=\"M280,106 L318,106\" stroke=\"#6b7484\" marker-end=\"url(#ev1)\"/><rect x=\"320\" y=\"72\" width=\"112\" height=\"68\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"376\" y=\"98\" text-anchor=\"middle\" class=\"svg-t\">生成</text><text x=\"376\" y=\"120\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">事实/引用/拒答</text><path d=\"M432,106 L470,106\" stroke=\"#6b7484\" marker-end=\"url(#ev1)\"/><rect x=\"472\" y=\"72\" width=\"112\" height=\"68\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"528\" y=\"98\" text-anchor=\"middle\" class=\"svg-t\">工具与策略</text><text x=\"528\" y=\"120\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">权限/参数/副作用</text><path d=\"M584,106 L622,106\" stroke=\"#6b7484\" marker-end=\"url(#ev1)\"/><rect x=\"624\" y=\"72\" width=\"80\" height=\"68\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"664\" y=\"98\" text-anchor=\"middle\" class=\"svg-t\">结果</text><text x=\"664\" y=\"120\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">解决/转人工</text><path d=\"M664,142 C650,207 246,214 224,143\" fill=\"none\" stroke=\"#6b7484\" stroke-dasharray=\"5 4\" marker-end=\"url(#ev1)\"/><text x=\"450\" y=\"199\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">生产失败回流：保留 trace、证据和版本，形成新评测样本</text></svg><figcaption>图 1　端到端结果决定能否上线，组件指标负责解释为什么；只有后者没有前者会局部最优，只有前者没有后者则无法诊断。</figcaption></figure><p>例如最终答案无引用，原因可能是检索没找回条款、上下文被截断、提示未要求逐项引用，或渲染层丢了 citation id。分层记录才能把“模型不行”改成可执行修复。</p><p>应用评测输入版本化的输入、检索、生成、工具策略和界面链路，输出组件诊断与端到端业务结果。端到端指标决定能否发布，组件指标定位第一次偏离；无引用可能来自召回、截断、提示或渲染。组件局部提高不代表完整任务提高，诊断也不能替代最终验收。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>样本应来自任务分布而不是灵感题库<span class=\"dd-badge eng\">数据</span></h2><p class=\"dd-lead\">十个精心编写的正常问题，为什么会制造虚假的安全感？</p><p>真实流量包含错别字、口语、信息缺失、冲突政策、多轮补充、超长附件、越权要求和提示注入。应从高频任务、高损失任务、历史事故、边界组合和真实抽样五个桶构建数据，并标记语言、客户群、渠道、长度、工具和风险切片。</p><ol class=\"dd-steps\"><li>开发集用于日常调提示，允许频繁查看。</li><li>冻结门禁集只在候选版本成熟后运行，减少测试过拟合。</li><li>挑战集故意集中长尾和对抗案例，不应用其比例估计总体成功率。</li><li>线上抽样集估计真实分布，需脱敏、权限审查和时间窗口。</li></ol><div class=\"dd-note warn\"><b>反例：</b>把挑战集 30% 的攻击样本按真实流量权重平均会低估正常体验；完全不看挑战集又会掩盖低频高损失风险。应分别报告。</div><p>样本设计输入真实流量、高损失任务、历史事故、边界组合和对抗场景，输出带语言、群体、长度、工具和风险标签的数据集。开发集用于迭代，冻结集用于门禁，挑战集暴露长尾，线上抽样估计真实分布；四者不能混用同一权重解释。挑战集比例不等于生产发生率。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>评分器是一组需要校准的测量仪器<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">LLM 裁判说“合格”，真实质量就一定合格吗？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>属性</th><th>优先评分器</th><th>为何</th><th>剩余盲区</th></tr></thead><tbody><tr><td>金额/日期</td><td>程序断言</td><td>确定、便宜、可复现</td><td>输入真值可能错</td></tr><tr><td>工具副作用</td><td>沙箱状态差异</td><td>直接检查真实结果</td><td>模拟与生产差异</td></tr><tr><td>证据支持</td><td>主张—证据核验</td><td>定位到原文跨度</td><td>来源本身可能过时</td></tr><tr><td>帮助性/语气</td><td>盲化 LLM + 人工</td><td>处理开放语义</td><td>顺序、长度和文化偏差</td></tr></tbody></table></div><div class=\"dd-formula\"><math display=\"block\" aria-label=\"观测分数的测量误差分解\"><mi>ScoreObserved</mi><mo>=</mo><mi>Qtrue</mi><mo>+</mo><mi>Bjudge</mi><mo>+</mo><mi>Esample</mi></math></div><p>用一批双人标注并经仲裁的金标样本，计算裁判在各切片的精确率、召回率和一致性；交换候选顺序检查位置偏差，统一长度或明确 rubric 降低文风偏差。模型裁判不能读取候选中的指令性文本来改变评分规则。</p><p>测量模型输入潜在质量 Qtrue、评分器系统偏差 Bjudge 和样本随机误差 Esample，输出观测分数 ScoreObserved。分数是三者叠加的结果，所以 LLM 裁判也需用人工金标测精确率、召回率、位置和文风偏差；它是测量仪器，不是真值。高风险确定属性应优先程序或状态检查。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>运行示例：平均提升为何仍不能发布<span class=\"dd-badge math\">案例推演</span></h2><p class=\"dd-lead\">新版本总分从 80.0 升到 83.2，但越权率也上升，应该上线吗？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>切片</th><th>流量权重</th><th>旧版通过率</th><th>新版通过率</th><th>失败成本</th></tr></thead><tbody><tr><td>普通资格问答</td><td>70%</td><td>84%</td><td>90%</td><td>1</td></tr><tr><td>金额计算</td><td>20%</td><td>75%</td><td>78%</td><td>3</td></tr><tr><td>越权请求</td><td>10%</td><td>65%</td><td>45%</td><td>12</td></tr></tbody></table></div><p>普通加权通过率：旧版 <code>0.7×84+0.2×75+0.1×65=80.3%</code>，新版 <code>0.7×90+0.2×78+0.1×45=83.1%</code>，新版看似提高 2.8 点。但若把失败概率乘严重度，旧版风险损失为 <code>0.7×.16×1 + 0.2×.25×3 + 0.1×.35×12 = 0.682</code>；新版为 <code>0.7×.10 + 0.2×.22×3 + 0.1×.55×12 = 0.862</code>，反而恶化约 26%。</p><p>实际门禁不应依赖一个争议性效用权重，而应先规定越权切片“不得低于旧版且至少 60%”。新版直接失败。成本权重用于排序修复优先级，硬门槛用于保护不可交易的约束。</p><div class=\"dd-note warn\"><b>不要把数字伪装成价值共识。</b>　失败成本由业务、法律和受影响人共同决定，不是评测工程师单独填写的技术常数。</div><p>门禁案例输入切片权重 wi、通过率 pi 和失败严重度 ci，输出加权通过率 PassWeighted 与风险损失 RiskLoss。前者求 Σwi×pi，后者求 Σwi×(1−pi)×ci；新版总通过率提高但 RiskLoss 从 0.682 升至 0.862，说明高风险退化不能被平均抵消。争议成本只用于排序，越权仍应用硬门槛。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"切片加权通过率与风险损失\"><mi>PassWeighted</mi><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><mi>wi</mi><mo>×</mo><mi>pi</mi><mo>;</mo><mi>RiskLoss</mi><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><mi>wi</mi><mo>×</mo><mo>(</mo><mn>1</mn><mo>−</mo><mi>pi</mi><mo>)</mo><mo>×</mo><mi>ci</mi></math></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>组件消融把相关性变成修复线索<span class=\"dd-badge eng\">诊断</span></h2><p class=\"dd-lead\">端到端掉分后，怎样判断是模型、检索还是提示造成？</p><p>保留同一批输入做受控消融：给生成器 oracle 正确证据，若仍答错，问题偏向生成或规则；固定旧模型替换新检索，测召回变化；回放相同 tool responses 隔离工具波动；将输出交给独立渲染测试检查 citation id。</p><p>组件分数并非最终目标。检索 Recall@5 提升可能塞入更多干扰，反而降低生成忠实度；工具调用准确率高也可能在不该调用时过度行动。消融的价值是缩小因果候选，而不是证明单一组件独立决定结果。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>实验</th><th>控制</th><th>可支持的结论</th></tr></thead><tbody><tr><td>oracle 证据</td><td>直接给金标条款</td><td>区分召回上限与生成利用</td></tr><tr><td>同模型换索引</td><td>提示/采样不变</td><td>估计索引版本影响</td></tr><tr><td>工具回放</td><td>返回固定</td><td>隔离外部服务波动</td></tr><tr><td>规则开/关</td><td>成对运行</td><td>估计护栏收益与过拒绝</td></tr></tbody></table></div><p>组件消融输入同一批样本、冻结的其他变量和一个待替换组件，输出检索、生成、工具或渲染对端到端差异的因果线索。oracle 证据消除召回限制，工具回放隔离外部波动，规则开关估计护栏作用；一次改变多个因素无法归因。消融只缩小原因候选，最终仍以业务任务验收。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>离线、影子、小流量与正式发布<span class=\"dd-badge eng\">闭环</span></h2><p class=\"dd-lead\">离线集通过后，为什么不能直接全量切换？</p><p>离线回放快且安全，却看不到真实用户反应和外部服务变化；影子流量让新版处理真实请求但不展示结果，可测分布、成本和工具读操作；小流量发布才观察真实交互，但必须有实时硬护栏、停止规则和回滚。</p><ol class=\"dd-steps\"><li>离线门禁：所有硬切片过线，主指标差值区间满足要求。</li><li>影子：验证容量、延迟、版本记录和真实输入覆盖，不执行不可逆工具。</li><li>金丝雀：按稳定用户单位随机，防一个会话跨版本；监控伤害、完成率与人工接管。</li><li>扩大：每级保持观察窗口；超过越权、p95 延迟或错误预算立即回滚。</li></ol><p>用户点赞是弱信号：沉默不代表正确，满意度也可能奖励过度承诺。线上行为指标要与抽样人工审查和确定性业务结果组合。</p><p>发布流程输入离线门禁、影子结果、金丝雀指标和回滚阈值，输出继续扩大、停止或回滚决定。离线先证硬切片，影子测真实输入和容量但不执行不可逆动作，金丝雀才观察真实交互；每级保持观察窗口。越权、尾延迟或错误预算超线必须自动停止扩大。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>评测集会老化，也会被团队过拟合<span class=\"dd-badge intuition\">治理</span></h2><p class=\"dd-lead\">持续把失败加入测试集，为什么仍可能越测越不可信？</p><p>如果每次失败都直接加入固定集、团队随后针对这些题调参，集合会逐渐成为训练信号；重复近邻让某种事故被过度计权，旧政策又使答案失效。每条样本需有来源、创建时间、适用政策、个人信息处理、去重簇和退役条件。</p><p>把“发现池→审核→开发集→下一版冻结集”做成版本流程。当前发布门禁一旦冻结，不能因候选失败而删题或改 rubric；必要变更要升版本并同时保留旧版结果。数据漂移监控负责提示何时重采样，不应看到分布变化就自动重训。</p><div class=\"dd-note warn\"><b>失败边界：</b>评测只能降低已建模风险，不能证明开放世界里绝对安全。低频不可逆动作仍需权限约束和人在回路。</div><p>评测治理输入样本来源、时间、政策版本、隐私状态、近邻簇和退役条件，输出发现池、审核、开发集、冻结集及下一版本的迁移记录。失败样本直接加入并反复调参会使门禁变成训练集；当前冻结集不能因候选失败而删改。开放世界低频不可逆风险仍需权限和人工控制。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与延伸学习</span></h2><p class=\"dd-lead\">好的应用评测既能做上线决定，也能告诉团队下一步修哪里。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>模型榜单高，产品就更好</td><td>应用还取决于数据、工具、策略、界面和目标分布</td></tr><tr><td>测试题越多越可信</td><td>代表性、独立性和标注质量比数量本身重要</td></tr><tr><td>平均分能概括一切</td><td>高风险门槛、切片和成本延迟不能被平均掉</td></tr><tr><td>LLM 裁判可替代人工</td><td>它是经校准的仪器，不是真值来源</td></tr><tr><td>线上 A/B 会给最终答案</td><td>需要安全边界、稳定分流和长期效应解释</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>模型评测、概率统计、RAG、工具调用</td></tr><tr><td><b>本页核心</b></td><td>评分契约、切片、评分器校准、消融、发布门禁</td></tr><tr><td>证据闭环</td><td>可观测性、数据漂移、引用与证据对齐</td></tr><tr><td>风险延伸</td><td>红队测试、护栏、人在回路、不确定性校准</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>把业务成功拆成可判定属性</li><li>从真实分布构造版本化样本</li><li>组合并校准评分器</li><li>运行端到端与组件消融</li><li>按硬门槛/切片/成本决策</li><li>把生产失败经审核回流下一版</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>为什么总分提升不能自动上线？</li><li>oracle 证据消融能诊断什么？</li><li>LLM 裁判为何需要金标集？</li><li>挑战集为何不宜按原比例估总体成功率？</li><li>当前门禁集失败后为何不能删题？</li><li>假设“LLM 应用评测：测量整条系统是否完成真实任务”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>关键风险切片可能退化，硬约束不能被普通质量补偿。</li><li>在检索上限被消除后，剩余错误更可能来自生成、规则或后处理。</li><li>测出位置、长度、同源等偏差和各切片可靠性。</li><li>它刻意过采样长尾风险，不代表真实流量权重。</li><li>这会把测试反馈变成调参信号并夸大泛化，应在下一版本治理。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://platform.openai.com/docs/guides/evals-design\" target=\"_blank\" rel=\"noopener\">OpenAI Evals Design Guide</a>：目标驱动评测与持续改进</li><li><a href=\"https://arxiv.org/abs/2309.15217\" target=\"_blank\" rel=\"noopener\">RAGAS</a>：RAG 组件与端到端评估</li><li><a href=\"https://arxiv.org/abs/2305.14251\" target=\"_blank\" rel=\"noopener\">FActScore</a>：原子事实级评估</li><li><a href=\"https://www.nist.gov/itl/ai-risk-management-framework\" target=\"_blank\" rel=\"noopener\">NIST AI Risk Management Framework</a>：风险测量、管理与治理</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
